BEGIN;

SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (309::BIGINT, 'Hay lecturas semanales, examenes no tan mortales donde el mayor enemigo es el tiempo, Faltó 4 semanas y en clases explicaba el código de las lecturas. Es buena gente y da mucho énfasis a que uno documente bien y use Linux y Git. Calificó el 60% del curso la semana de entrega de actas'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '376bc66ecddc04a831defdbfffeb1d8abdaf81131819f661a8a767dfd034aed2'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Esteban es bueno en las clases, resuelve dudas y explica bien, pero deja tareas demasiado largas y poco necesarias, hay que hacer un resumen de lectura semanal que es 0 provechoso, los exámenes son muy largos y no da chance. Aparte canceló muchas clases. La calificación de los proyectos es ambigüa.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2026-01-31T00:00:00+00:00'::TIMESTAMPTZ, '46310e9eaf7cb3179353c50d8475de2c73e0931314eca4260a8ab7df81e6ddc2'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Esteban es el mejor profe para tanto FOC y Arqui,es medio matado, pero terminas aprendiendo demasiado. Eso sí, vas a hacer reportes de lectura de manera semanal. Sus exámenes y tareas suelen ser largos y de dificultad media. Es flexible con las progras. Quices sorpresa, por lo que es obligatorio ir'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-12T00:00:00+00:00'::TIMESTAMPTZ, '8b3a8d0ec52347528a802d02e4a21c41b6ae266bd7466a1d587295b0f48de29b'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Como profe es buenisimo y como persona también. Hay lecturas semanales hasta semana 12 (lo más pesado del curso). Se aprende muchísimo, tanto ensamblador como arquitectura, y sus explicaciones super claras. Se preocupa por sus estudiantes, y nos ayuda mucho. Nos llevo merienda a un examen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'ce3cff9afdcdcd1b5b7579ad57724124ce6330550c3b8607c24ce8c244d4dccf'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Hay que hacer resúmenes de lecturas por todo el semestre, pero nada muy difícil, hace quices sorpresas, pero con ir preparado es fácil, además es muy flexible con las tareas y progras. Lleva comida para los estudiantes en los exámenes. ????'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'db63e54f65027751a72769934b6c679a4f26d341ec28c5386ff322e2b10afaf7'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Son clases agradables, el profe explica super, aveces hace quizzes sorpresa, hay lecturas todas las semanas, dan pereza pero se aprende si las hace. Recomendado, al principio del curso intenta meterle miedo a uno, pero solo es para que se pongan las pilas, lleva comida para uno en los examenes'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2025-11-12T00:00:00+00:00'::TIMESTAMPTZ, '87f2d0880c139371878479e98d48169aa2c251a58d577f2e503b370795f7c712'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Esteban es un buen profesor en general, y una gran persona, es cierto que es laborioso pero no pierda la oportunidad de llevar con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '63fd864a811a4fe297aab84921f557bd5905b9b6e15babfe8b8cb1c7facfbdf9'::TEXT, ARRAY[1121]::BIGINT[]),
    (309::BIGINT, 'Muy buena persona y buenísimo profesional. Clase bastante dura: 3/4 resúmenes por semana hasta semana 13 (sorprendentemente lo más tedioso jaja), tareas, TC, 2 proyectos fuertes, exámenes. Aunque este semestre estuvo tan ocupado con sus cosas de IEEE que a ratos le costó mantenerse con nosotros.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'd06533887fa6713a6bf864c6cbc767e3db2d8250cc8b9b0a8faf05c82d6ef8a7'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'El profe deja lecturas cada semana y debes hacer un mapa conceptual para cada lectura y eso vale un 5%. El profe deja tareas que sorprende a uno pero no son dificiles si le pones. Los proyectos no son tan locos. hace examenes, 3 en total pero nada dificil comparado con otros profes'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-03T00:00:00+00:00'::TIMESTAMPTZ, '093ab5bab262990503cfac38ad5494cb800e6c52d08044d50b6fd81233cb7ea2'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Esteban es top 3 mejores profes de compu, deja muchas tareas pero reconoce muy bien el trabajo duro de los estudiantes. Vaya al día y haciendo todo a conciencia y le aseguro que de fijo pasa.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'c5beaa8a9b8e3fb00a501e7d4cac1fc7066c22af6e149c194d8a48f3b5cce9dc'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Esteban es excelente como profesor y persona, es super flexible con las entregas. Nada mas que no manda calificaciones hasta entrega de actas, entonces es dificil saber como va uno hasta el final'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-28T00:00:00+00:00'::TIMESTAMPTZ, '9ae483b227fb0ee8ae6b267c3727950dbdc24b6590fb5da2f90396334558ee9e'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Él es de los mejores profes que usted podrá encontrar en la carrera. Habrán bastantes tareas cada semana pero no son muy largas. Procure participar y asistir a clases y verá como él lo tomará en cuenta y le irá muy bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-30T00:00:00+00:00'::TIMESTAMPTZ, '815784ebd0bbf66cb043ae8fd57da2a744f9acbcd53452924b37119dd5525759'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Buen profe, explica todo de manera clara, ayuda con los tiempos de entrega y es bastante flexible con esto, siempre y cuando se entreguen los trabajos y sean se calidad. Procure participar para que vea su interés y lo ayude si ocupará algo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '08956bcf7ae952adf10c4b7a09a767c1a9975822e5184c375b2e5f4cd16dc965'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'El curso fue asincrónico, solo la primera clase y las exposiciones de los proyectos fueron sincrónicas. Semanalmente se trabaja en resúmenes. Los proyectos son de investigación, documentación o prototipos(no se programa). Ninguna evaluación fue muy complicada pero si lleva su tiempo de trabajo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '87f65e53d285dc116a57d8d47705b8eb0abdd9c3f02014843af754287618aef3'::TEXT, ARRAY[1156]::BIGINT[]),
    (309::BIGINT, 'Es muy flexible con la fecha de las entregas. Deja proyectos y exámenes super fáciles. Deja muchas lecturas en inglés'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4458544b8733d87e3021b231b199e863904784709ffdf50e14e7c30e3cc2230b'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Es de las mejores opciones para FOC, aunque el curso es obviamente duro, la carga académica siempre está equilibrada y los trabajos son de una extensión razonable. Siempre y cuando uno se mantenga al día, el curso se puede pasar con cierta facilidad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '125729540cdd1951b0b5c0fed000a8b0ef06a8b0099f8e0b2f21d33dca3795ce'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Deja muchos trabajos por entregar, tiene muchas reglas que hay que seguir para entregar los trabajos, los proyectos o trabajos programados son muy difíciles, de los cuáles con lo que se enseña en clase(pura teoría) no es suficiente. Si llevas muchos créditos es mejor evitarlo.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'd398dc4e0db9c4babd3f4538ea5aeba1109a819b934f2622db4ac7b212ff861a'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2022-09-15T00:00:00+00:00'::TIMESTAMPTZ, '22ef2215fcc9299899b06ca4cda1e7f9304b6480c71dd32d0b496db8a169a6f3'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'No es tan malo como dicen, es súper pura vida y atento. Puede que no sea muy claro con lo que pide, pero sí uno le pide que le explique de nuevo él lo hace. Siempre estuvo atento a las necesidades de los estudiantes y nos daba tiempo extra para entregar trabajos. Diría que es de los mejores en FOC'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '0aa470e5cab127d37325fe7c0d200a7c3364a21327465941c81eb5296d0d4993'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Si no se quieren complicar la vida, no matriculen con él, deja demasiados trabajos y las indicaciones no son nada claras, un día dice algo y al otro dice lo contrario, para un curso de primer semestre hace las varas super confusas'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-03-01T00:00:00+00:00'::TIMESTAMPTZ, '23b7ce8c5624ed14ef19b9e49cfa5a27c3bb41b2eee81c66b263bf8e3ef97fc7'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'El mejor profe para arqui, explica bien, dejan quices que uno debe pensar y luego entiende la materia con ellos, da tiempo si se le explica por qué.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2022-02-03T00:00:00+00:00'::TIMESTAMPTZ, '0a59b07ee55ac6db6592d14f43f6da0496e23a8c36ae4dfc36f7f6be312005a3'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'El profesor no es claro en las cosas que pide, aparte de eso lo que se ve en clases no ayuda en nada para las tareas y proyectos. Con respecto a las clases siempre las pasaba suspendiendo porque le interesan más otras cosas como IEEE que los cursos que da, suspendió la mitad de las clases.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2021-12-15T00:00:00+00:00'::TIMESTAMPTZ, '9c252e245a82d8ec1bb2400d23e9b5c1d6201d0ef05b949c9a5ce8a921407cba'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Buen profe y buena persona, las asignaciones son de dificultad moderada y el mae extiende las fechas un pichazo, califica descendete, la gente que le hecha hate al mae es porque no les gusta entender las lecturas que el mae deja porque con el libro del curso usted hace todo'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '92d0b5c173b633b46fbb902351ef506c43a6ce00d56c8cca3bb34c60f7f78cf2'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'El peor, cancelo la mitad de las clases, aspectos de calificación no claros, ni él sabe lo que quiere, para el proyecto y las tareas usted está solo porque él no enseña nada que le sirva para hacerlas, solo dice que en el material que brindo (enunciado) está todo y que la asignación está muy fácil.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'a8b6db876eedae3cd3a23b452fa3a08ed3190e61c3076ee3cd363fdab85ede06'::TEXT, ARRAY[1054]::BIGINT[]),
    (309::BIGINT, 'Es excelente, la mejor opción para arqui, solo ponga atención y realice los ejercicios de NASM y todo sale regalado. Quices sorpresas en clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2021-07-27T00:00:00+00:00'::TIMESTAMPTZ, '152331beee17015f1b248a9ff87487d7a767683f568cf42a8c1597b3ee1397db'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Maes no duden matricular con el es súper buen profe, y hay 2 clases más de 60 estudiantes que lo pueden confirmar, nada más pongalen con los bretes y van a ver que vale la pena, super buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, '4196044cef84fc9a2a8474c09e1579f3e7947efdb357eb30119826d6eac312e5'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Explica bastante bien la materia. Se entregan lecturas todas las semanas, se realizan varios quices y tareas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '1a37112065225f631c3521bc55e2cc91e647adc1af04c6d641fb05401c49d039'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Deja muuuchas tareas y lecturas en las primeras semanas, pero estas ayudan a pasar sin importar que le vaya maso en exámenes y proyectos. Varios quices sorpresa en media clase,; el profe es muy empático y siempre escucha y ayuda, califica siempre viendo el lado bueno.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '57ec3b14df77896628abd3927fa37a3bf8122bf8607d39c0ab1238482da7321f'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Un profesor excelente, lo recomiendo muchísimo. Deja bastantes actividades, las cuales son entretenidas y ayudan mucho al aprendizaje, no son para nada pesadas. Es muy respetuoso, siempre está dispuesto a escuchar la opinión de los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '30266833f9fd616637dc81e73e585826b710677f38ef016f15b1926f78cbbdb0'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Esteban es un excelente profe, explica muy bien y deja asignaciones que son fáciles si le dedicas tiempo a repasar la materia y a mantenerte al día, pero las instrucciones de estas pueden ser confusas. Hay quices sorpresa, la participación en clase importa.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'f41c41083d2bbcb0f6e59fb12565c3f431598479df43c3c3e31a3ef5b98d7d7e'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Deja muchas tareas al inicio que no valen para nada; al final hay que estar corriendo con los proyectos y exámenes. Es muy desordenado y las clases son a medias, explica muchos conceptos, pero sin dar ejemplos claros. Aún así, es muy pura vida, le ayuda en lo que usted le pida y da puntos extra'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9ef94c4454e4d22984f1990b650c3b368e31e81b479eb295ff63fdd408155325'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'En mi opinión uno de los mejores profesores de computación, pide trabajos que lo hacen a uno investigar y aprender, en las revisiones si uno comete un error le dice como arreglarlo para que no le pase con otros profes, todo se le entiende, lo que si tiene es que es un tanto desordenado. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '06322594d00d2d526516e02102e1194c777d92e14f248234303b16a2f1d1b99a'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'muy desordenado, no se le entiende'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '38df644108342ba89fea9750d2110f2a761132c7e66ef1ebc9c4957412c13109'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'Es un buen profesor, explica muy bien y con pizarra. Deja bastantes trabajos pero eso es bueno porque si los hace aunque le vaya mal en el examen pasa. Los dos proyectos que dejó en realidad no estaban difíciles. Además se nota que le importa mucho sus estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '64f0999ebb052fb624987f5c848b54728bd211050b6debca8f28f0493ea26964'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'Deja bastantes lecturas y tareas que implican documentación y dedicar bastante tiempo para investigar. Hay que ser bastante autodidacta. Las progras son relativamente sencillas, pero es importante irlas sacando con tiempo, así como asistir a la clase y demostrar interés.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '707dcc1d1141f7c40a76b79c0a37fc56ff7463b4ae171fcf90aec7127ca78563'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'No lo recomiendo a no ser que no quede de otra. La materia la imparte MUY confusamente, deja muchas lecturas, las explicaciones en pizarra son horribles y lo peor es que no enseña lo suficiente (énfasis en estructuras) por lo que iràs renco a los cursos que a futuro implique. Da puntos y màs tiempo.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Da crédito extra']::TEXT[], '2021-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'dc330003d0d48e10cae292197372a28f3f70d3f5fbddc45f9dcab61ea02cb05d'::TEXT, ARRAY[1017, 1032]::BIGINT[]),
    (309::BIGINT, 'El curso es algo aburrido y hay que leer mucho. El libro que se usa es de hace más de 20 años. Uno puede aprender mucho por su cuenta. El curso es bastante sencillo en general y las progras son un queque. Recomendada si solo quiere llevar una electiva fácil.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2020-10-07T00:00:00+00:00'::TIMESTAMPTZ, 'd6e5eebdf0d5db0cc57050429e08f3679323b4bd0b8fded4b3acbb0f78ee1d82'::TEXT, ARRAY[1121]::BIGINT[]),
    (309::BIGINT, 'Si hace todos los trabajos y no le va mal en la mayoría se pasa. Su problema es que explica como si ya uno supiera sobre el tema, si alguien ya sabe sobre lo que él habla supongo que tiene sentido pero si no sabe no se entiende mucho. Tiene un tono muy monótono y eso aburre la clase.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'a7ff649b4fbe1bbca20bbdcb51c164d4a36b58faf10449d49a0c6e6064826387'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Sabe de sistemas operativos, pero los proyectos son más orientados a redes que otra cosa. El curso se vuelve demasiado pesado, tómelo como de 6 créditos. Las lecturas quitan MUCHO tiempo y valen una cochinada. Entrega notas cuando le da la gana. Califica como quiere a la hora de entrega'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '5fbc4637ce8f1dbfdd04197e9061b02665460b6bbfca79f29dc8a71de65fbe8c'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'La verdad su clase es aceptable comparando los otros profes que la dan, si usted hace todos los bretes y se esfuerza es muy probable que pase el curso, eso si, el último proyecto es una mrd Y ANDA MAMANDO CON ARDUINO, se pone un proyecto así y cree que todos lo tenemos dominado sin explicar nada.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '8c2ac57af60d6032b548f93dbcce9432c3affd614e1c55779289cca14814212e'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Tiene absolutamente todo lo malo que puede tener un profesor, no da notas hasta el día de entrega de actas, atiende dudas cuando le sale del culo, él mismo crea problemas que nunca deberion existir, pide una cosa en los proyectos y luego en la revisión dice que era otra, se contradice solo, etc...'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '88f273f20b61122ee3c8a1fa9bf17adc776b393dac5844fd45e2d787a5a5b0b9'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Por profesores como él me cuestiono la seriedad de la Escuela. SO? qué es eso? para él el curso es redes. Notas? Olvídese, el día de entrega de actas (a dos días de entrega no tengo mi nota). Ayuda? eso no existe aquí. Si lo tiene matriculado lo invito a quitar el check, es por su salud mental.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'f381ad9ec177d8cde3a948db2738372b2c4d2eefbd3bfbe2f37ed5d6aa9f1ada'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Siempre llega tarde, muchas lecturas y tareas largas. Por cambio de carrera llevaba este curso de primer ingreso, uno de segundo semestre y uno de tercer semestre, este curso fue el que consumió más tiempo y más difícil. Enseña a soldar y básicos de Arduino y yo huyendo de electrónica ????????'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '8fdfceac2dbc501208350ba09c17d819de973d4cb58c018e41b29dc20dc755ca'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Es un buen profesor, el curso se pasa solo, pero tiene que ponerle y hacer todos los trabajos, preparese para hacer los resumenes de trabajos por semana y proyectos muy extensos, y normalmente hay un quiz todas las semanas de la materia vista en la clase anterior, solo no deje todo para el final'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, '6ac235cc30fe999d4b3e417ab44e33c2adcce89b43b423b53590307b9384510a'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Segundo semestre 2019. Se nota que no maneja el tema de IA. Solo se ven tecnologías y temas que están desactualizados con el mercado laboral. Super irresponsable, estuvo ausente la mitad del semestre pero aún así dejó trabajos que requerían de mucha ayuda. No lo recomiendo en lo absoluto.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2020-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'e4ea8dad05dd2c7d5497a62a7bf5c67a0ae9a119c950a3c37bbbf95c9ff09efe'::TEXT, ARRAY[1162, 3790, 328, 3075]::BIGINT[]),
    (309::BIGINT, 'Digamos cuando da clases algo se le entiende. El problema es que nunca llega y hace exámenes durísimos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-02-11T00:00:00+00:00'::TIMESTAMPTZ, '811a45103d5584668099f7dcbb03b470ccc2530560bfe2b0d81cb08492079622'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Curso sencillo, llevadero a pesar de ser verano. Se habla mucho en clase y hay que hacer unos reportes y ensayos. Los proyectos son acordes al curso, una investigación y otra actividad diferente. Se pasa un buen rato. Flexible con las entregas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2020-02-02T00:00:00+00:00'::TIMESTAMPTZ, '6677dd8bcf7e0849f7f29edee423e82cd3427dfa2eeff57ee53b5541d9ceb235'::TEXT, ARRAY[1156]::BIGINT[]),
    (309::BIGINT, 'Tiene que saber ser auto didacta, es buena persona pero las clases se vuelven repetitivas. Puede hacer quices sorpresa de la materia que se vio la clase anterior. Proyectos y Tareas complejos, MUCHA investigacion, NO LOS DEJE PARA ULTIMO. Lecturas semanales de varios capitulos.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-01-29T00:00:00+00:00'::TIMESTAMPTZ, '8be03a939d5ec96079863236295ad9b7d05269bbfbdc60650ef666f97d73f1b6'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Las clases que da las da bien, pero casi nunca da. Es muy buena gente, pero solo le interesa estar viajando y al final ni le interesa lo que aprendan los estudiantes. Muy vago, no da los quices y la nota de las tareas los da después para evitar reclamos. No sabe como redactar las tareas, muy malo.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-12-14T00:00:00+00:00'::TIMESTAMPTZ, '3665340183b34731b25934898f54d1d8dd23c4999e0451d32485210ba3ec322d'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Profesor irresponsable que se fue la mitad del periodo lectivo de paseo. En clase "enseña teoría de Inteligencia Artificial de los años 90. Deja proyectos aburridos y largos de pura sentencia If Else, esa es la IA que conoce.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '32056f7ee473af3ecd2bbd5a37a1bf8ea64e8229feafe5d14d577abf047fab0f'::TEXT, ARRAY[1162, 3790, 328, 3075]::BIGINT[]),
    (309::BIGINT, 'Muy buena gente como persona. Faltó a la mitad de las clases, un poco irresponsable en cuanto a revisiones y puntualidad. Sin embargo, sería mentir decir que no aprendí nada, sí se aprende bastante.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '26b02484b529a2be1aca29f4e19c5d7ec224dee7d208332a443ae4a9be35ea10'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'La mitad del semestre se dedico a repetir lo que se vió el semestre pasado en FOC y la otra mitad no dio clases , no se aprendió nada. Siempre llega tarde (cuando da clases) incluso a los exámenes. Solo dio una clase para el examen final y no cubrió los temas de éste.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'f707576b4acadd2e48621e6055cac7d4c35579e117adcc1490c6dd7af81518f1'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Pésimo profesor, no sabe nada de IA. En clase únicamente lee presentaciones y no explica nada. Se ve materia muuy vieja y como siempre, impuntual. Una pérdida de tiempo llevar el curso con él.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2019-11-18T00:00:00+00:00'::TIMESTAMPTZ, '41a806c8564ec92b4d56ca6660d57d06c61ce25b750f0848c265608c8b453928'::TEXT, ARRAY[1162, 3790, 328, 3075]::BIGINT[]),
    (309::BIGINT, 'No lo recomiendo en lo absoluto. Se ve materia de hace mil años, solo se pone a leer presentaciones en clase y no explica bien. No sabe de la materia. Muy impuntual (como siempre). No le interesa el aprendizaje de sus estudiantes. Si de verdad querés aprender IA busque otro profesor.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'b4ddd3372a1df15019032f2f3c371471ab4aba7f1b917cab2b6fc2ef0023469d'::TEXT, ARRAY[1162, 3790, 328, 3075]::BIGINT[]),
    (309::BIGINT, 'Tuvimos al rededor de la mitad de las clases a lo largo del semestre.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-11T00:00:00+00:00'::TIMESTAMPTZ, '0b9cdf855e090e2aac4ce4fa982b839ea632d61d06555658cff284d27c692e68'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, '0 ayudas, lenguaje obsoleto que dificulta más aún las tareas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-09-01T00:00:00+00:00'::TIMESTAMPTZ, '722af7b0d5ffe3089a83d1e4edd0d1fd369afe1c1b249172ce9fb69330793111'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'Es una calidad de persona, muy pura vida, al principio deja trabajos muy largos pero al tiempo uno le agarra el toque para resumirlos, si hay algún problema con fechar o cualquier cosa está dispuesto a cambiar fechar de entrega para ayudar. Siempre llega tarde xD'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, '41e41ca7e4e6b946f499cd3b2f455569783960fec87202df530f7bb89e4bcddf'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Las clases y evaluaciones escritas son 99.9% orientadas a Biología, y los proyectos son mucha Computación con un poco de investigación. La materia fue bastante aburrida, no aprendí casi nada. Los trabajos quitaban bastante tiempo, pero es factible sacar buenas notas.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, '3f6bd33f6a2ab5c17c2bc850f8ccb1b1181237c29c1018963486944c6efad76c'::TEXT, ARRAY[1121]::BIGINT[]),
    (309::BIGINT, 'Es buen profesor y buena persona, se preocupa bastante porque los estudiantes aprendan.Las tareas y proyectos son largos pero no son tan complicados. Si tienen algún problema con el curso esta dispuesto a escuchar y tratar de solucionarlo.Siempre llega tarde.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '4266bdd86efa0af86edb886c982c57502e808fe517f97e3cfb55ec0ab78fa89d'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Como persona cae bien, a veces supone que la materia es sencilla pero es el mejor profe de los 3.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '5a779302547229df64ca487c8ddf9a07ca2ae5f422159f19057b9f8335628a8c'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Es una lotería, hay semestres donde enseña bien y otras donde es un irresponsable. Este semestre me tocó el profesor bueno. Explica bien, los proyectos son difíciles pero se aprende bastante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2019-06-05T00:00:00+00:00'::TIMESTAMPTZ, '4ad1a2ebf786ff07bce5b2fd240e7dcc56be9c5f10fbf66cda7b5532148cdd6c'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Excelente profe, explica bien y para las evaluaciones no pide nada que él no haya explicado, da puntos extra y muy buena nota.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-01T00:00:00+00:00'::TIMESTAMPTZ, '4a05729861dd8ec4abdaf96a3e58c29db8a25a9212e3ddb2a166ff241d4d9505'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'El profesor es un poco impuntual y desordenado, deja algunos trabajos largos pero que se pueden hacer si se les da su tiempo. Los examenes valen mucho porcentaje. Si hace todo seguro pasa'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'ac5148fbf58f22f24e86beb3b50a5b79aabca408c87bfc4bccd448656156a1bc'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'El profe es tuanis. Siempre llega tarde y a veces cancela clases faltando como 1 hora. Un poco desordenado porque deja todo para el final, explica bastante bien ensamblador. Exámenes fáciles si leen el libro(con hacer resúmenes es suficiente) y ponen atención. Proyectos ok. Entreguen todo y pasan.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2018-10-28T00:00:00+00:00'::TIMESTAMPTZ, '20f215e70e2fe21598b4ef17eed887d51c0cd6c70e93efc1e9ac058fb34b5fe5'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Pros: - Es alguien muy pura vida. - Sí le interesa que uno aprenda. - Sabe mucho. - Ayuda si le está yendo mal - Se aprende mucho Linux con él - Comunicación fácil (Telegram) Cons: - Impuntual - Mucho resumen a mano - Si uno no hace los resúmenes y labs le va mal en los examenes'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-23T00:00:00+00:00'::TIMESTAMPTZ, '0e234e9c4fe5d0b4cafbfdb8307dee5e9c4f163c3b0b12ffb62147d0d4e71c4b'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Desorganizado , inpuntual ,siempre llega tarde a las lecciones e incluso a los días de examenes , deja muchos resúmenes, examenes de selección única de aproximadamente 100 preguntas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b40e888aa9378e719fc7f26bd6dc0938b1bff98d00f8b61abf7d5abcbfadad60'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Un gran profesor, el cual tan solo pide que sus alumnos sean responsables con la educacion sin llegar al explotarlos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '40'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '8ae9c98e00ed737c8029dd12f667af9b90f061d03fe25cc187d25b81990fc13c'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Deja lecturas y laboratorios. Proyectos muy chivas. Si sigue hasta el final del curso lo más probable es que pase porque ayuda mucho. Aclara dudas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '2f243bedf14e7dd04d51c972403d2f9ee1f18fea6f41f3422eec50df2b392f71'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Uno de los peores profesores con los que he llevado, super vago e irresponsable, no le interesa que los estudiantes aprendan, se aprende más de las lecturas que de el, si quiere pasar un curso y no aprender nada, este "profesor" es una gran opción'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'f199d7d1ee290ab1e0fe5742ace1fd6582b94e1093ee2ce40aa7a31ff8aae1b0'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Muy buen profe, si quiere matarse en el semestre pero aprender mucho matricule con él.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'e1b00b704673b185efbf953e608ee25a54cf82abe34f126d2255c3c8cabfbd07'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Muchas tareas con instrucciones no muy claras, muy desordenado, resumenes que quitan mucho tiempo todas las semanas, llega demasiado tarde siempre y hace que salgan tarde siempre, pero...de los tres profes de FOC y arqui creo que es el menos malo. El profe es buena nota'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6ca873f66be886f9de11519727a1ea3910029930f572642d519cc90a2ab245de'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'La verdad es DEMASIADO desordenado con las tareas que deja y exige que uno sea muy ordenado y algo vago aunque es uno de las mejores opciones para Arqui.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '625909c71d1c68cff179ec9836b5791c728a2fa75fb1203087844d918bf91cba'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '645e4856a361d5abcfb483af7f583934c47ad68540e600a4f99909cf0b7e9675'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Profe súper buena gente, resumenes todas las semanas, muchas tareas, pero se aprende bastante. Los exámenes son fáciles y hace quices sorpresa (en la mayoría de clases), siempre intenta dejar todo claro y genera un buen ambiente en la clase. La mejor opción para este curso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'dc48f725953af053965d4bc81102168a33964ece4319d815b3311c93b6c495e3'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Quices cuando el profe no quiere dar clase, si llevó FOC con él, va a tener casi todos los resúmenes hechos, Tareas interesantes , resúmenes cada semana y exámenes de dificultad media. Los proyectos los deja, literalmente, al final del semestre'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e4bdbac3fcbf7988a12bc9a4b471cb74835002987339a0f69f2cf789b9c3287b'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Un profe muy pura vida, hace quices sorpresa y casi siempre llega tarde pero al mae se le entiende. Si usted está mamando él intenta ayudar. Recomendado'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b956f8dab11a581c5ebca187a7c6278dcb7c94fba4984be0631d3dbc76ba760f'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '976686a1d32d6c0357364168368dcbb1a6479254ecbefe6009ad3f688d66168a'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Buen profesor, buena persona no es el curso más sencillo pero no es difícil aprender y pasar con él'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '4a2b342f93c37f90b0881ae70da00b34eb1741b69ecedd460b2f98f84eb5636e'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'No es el profesor mas ordenado que hay ni el mas puntual , sin embargo es es buena gente , te genera la confianza para preguntar si tienes dudas y si le pones atención entiendes , deja muchos trabajos pero todos son posibles de hacer y si los entregas todos te va bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '48d81a08da975c67d3c2701c49d40ead71d80da3ff5fc802ad40877332c45f25'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd3ee5027813e53491e2b746c7639aaa2411c73a0379eb86c0205f151a21e683f'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Excelente profesor, se le entiende bien la materia, pero muchas veces dejaba cosas para tarea y no dejaba claro qué había que hacer para la tarea incluso hasta un día antes de la entrega, pero al ver que ninguno entendió, posponía la entrega. Demasiado buena nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '474bb4868939c5daf07ec97074ae36cc3048ee7ca6aa7b57e93bf8e4ccbd8e5e'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Demasiado desordenado. Faltaba mucho a clases y hacía quices de materia que no se vio justificando que eso estaba en las lecturas. Exámenes normales. Proyectos difíciles donde pone lo primero que se le ocurre cuando ni él sabe hacerlo. Explicaba bien la materia. Si quiere pasar, entregue todo!'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Clase fácil', 'Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '544a21889e823eef6f938c28e2c0ee54dd9ec7a4aacd3d610a119ee40681459f'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '1aa81a155b449bdc76808a7c3b6fb5c57b06ad5ee93b41ca998642731faaebca'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Siempre llega tarde, nos hace salir 20 minutos después de que se terminara la clase por horario. No ayuda en nada, asume que uno sabe muchas cosas que probablemente no sepa. Manda tareas con requisitos innecesarios con el fin de complicarlas. No lo recomiendo'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'af5f20366a2a092839b470f7e3a3805eb01f917b1c8d36eeb67de1bf317c103b'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'cddb7103affad3bdb6dd94d21f22580df1386350d7f7bdab0027f4d64043f098'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Llega tarde siempre y nos hace salir mas tarde justo cuando la clase es antes de almuerzo, Tareas super largas, y requisitos innecesarios que complican la tarea. Si se pide ayuda solo dice "lea instrucciones" y no ayuda, quizes sorpresa y por tanto rebajo de nota'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2018-04-03T00:00:00+00:00'::TIMESTAMPTZ, 'c517585f359050da71e81c8d0c8efdc61b9aa9f99483fd997fdaf8c87f1b1667'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'El curso es muy sencillo, lo único malo es que hay muchas tareas, pero si uno las hace con tiempo y se organiza todo sale bien :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'e0ebce15ff13ef1de1e3972f0b7f3863991c3c3fbe47b2ab4b053f740a514175'::TEXT, ARRAY[1156]::BIGINT[]),
    (309::BIGINT, 'El curso es interesante, se comparten opiniones sobre diferentes temas nacionales e internacionales, sin embargo para valer 2 créditos muchos trabajos escritos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '8ea2ab3593791b08d8ce2aa4919ea45dc86a3404c4738e0096277ea9218fe685'::TEXT, ARRAY[1156]::BIGINT[]),
    (309::BIGINT, 'A veces se confunde en clases, pero en general explica mejor que otros profesores, las clases se pasan rápido, se hacen trabajos con el Arduino y se aprende de todo un poco 100% recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, '1b7a9246f739f8f82c5e6de9fa6cad61ac89884f30799f46f87ddd42a0edac64'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Da buenas clases, pero solo cuando las da, llega tarde sin falta y es un desastre siguiendo su propio horario de entregas de trabajos, por lo que queda todo acumulado para el final. Explica bien y se entiende.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2018-01-10T00:00:00+00:00'::TIMESTAMPTZ, 'e5bab27cbc166abc97b4b61ede1ac9bad7ef76840c0e84fbcc9f54095d5835eb'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Es EXCELENTE. Llevé el curso con Benavides y en la segunda clase ya estaba perdido. Con Esteban se entiende todo y si él ve que uno le pone, lo ayuda demasiado a tal punto que infla la nota para tener 90 o 100, eso sí hay que entregar todo y dedicar el tiempo que requiere. Algo desordenado pero exc'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'e8badeddfa8328f88565e80b163a479cd51cab7d9d181f4a43c31e7a340c8154'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'El profe es tuanis, no entrega todo al día pero el curso es llevadero.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2017-07-07T00:00:00+00:00'::TIMESTAMPTZ, '067eb358c7487db569d17099dd77a7b6331c1650ad07bbfce7d8ac6b6425e244'::TEXT, ARRAY[1054]::BIGINT[]),
    (309::BIGINT, 'Es muy buena gente y accesible, los exámenes son muy fáciles, justamente lo visto en clase, el único "pero" es que cancela muchas clases. El proyecto super realizable. Recomendado! Califica suave.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b0cc47292216bba20a0e8f8b393185b4efa7eaeb482e85f1aba8d648cdb8c2d1'::TEXT, ARRAY[1054]::BIGINT[]),
    (309::BIGINT, 'Como persona es excelente, se nota que su intención principal es que sus alumnos aprendan y pasen el curso, las progras son relativamente difíciles, pero hay tiempo. Clases donde se mandan a hacer lecturas, y explica teoría y práctica en la clase. Si es fan de la puntualidad, no matricule con él.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c4c205eae7387c1e7307fa6d353e8234dcc3fed27c12ec78369a819b73291381'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Por razones personales de él no hubo clases una gran cantidad de días, sin embargo, en lo que pudo explicar fue muy bueno y claro. Se aprende bastante y la carga académica es adecuada pero las evaluaciones no se calificaron como se debe, a excepción del proyecto final. Recomendado!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '4818c9e4fdafb8db29a2ca10b91890a0a7993478a195120a5b87829d4bb489e5'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Las explicaciones de la materia de vez en cuando son un poco confusas, pero en general buenas. Es un profesor accesible, los exámenes son acordes a la materia vista y los proyectos son totalmente realizables.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ca7220eef694daf33110bb196e7620972d92c05ebc1dbeaad2435f6119251f91'::TEXT, ARRAY[1054]::BIGINT[]),
    (309::BIGINT, 'Si fuera más puntual a la hora de comenzar la clase, sería mucho mejor, si vas a consulta te ayuda, el curso el lo hace fácil, pero los exámenes son un poco cansados.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Da crédito extra']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '1243336235a3a80fa271f18d494068d972a1e433f76094d4d226134ae4781336'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'El profe es buana nota, si uno hace todas la tareas y estudia para los exámenes el curso se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Da crédito extra']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0186bd5c7e0eb4f6415108f20bab071445b27306510c3d9b3db27b2a5b2cea6e'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e6366c044555c3e257367480e8d6f02e67258f8a9d1871316799f745b4aae436'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e53888f1ddfff0a05fe9c96a88a82b8570a5316d5e1e89df1f501c91b2875bb1'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Clase clara, a pesar de no estar el 100% del tiempo, se aprende bastante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '92bb67dc302aee2f2a008286407800d456d999fdb5532de2db0a287ac1d58f1d'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Casi no tuvimos clases. No tuvo tiempo para revisar las tareas así que al final regaló 100 a todos. No se aprende casi nada.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'fea2c0f65c1c494802180836c61822a94c638bc0255d758c33e2cd1bcd82f466'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Curso que al matricular ya se asegura el pase. Explica muy bien, el problema es que cancela muchas clases que luego nos hacen falta para aclarar dudas de los proyectos que deja. Exámenes del semestre anterior. Fácil de pasar, pero si el curso lo da otra profe como Erika Marin, mejor con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '351555047bfe17917441d3e085399d631f6673f8fcd114f687a284860a901ab2'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Explica muy bien el funcionamiento de las computadoras. Con respecto a ensamblador se queda DEMASIADO corto, en ese tema sólo lee diapositivas, pero es pura vida.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '695c8fdcf84b52eb80f9349eef404e06350c77684568461633a5b48053411782'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Impuntual e irresponsable. Entrega exámenes como 2 meses después, siempre cancela la clase.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '898ba6ac7960408e844389923dea82f57596ea3b4502ea9a2f3cef795aa2eef7'::TEXT, ARRAY[1072, 1160, 2925, 1059, 1069]::BIGINT[]),
    (309::BIGINT, 'El profe al principio parece ser estricto, pero con el paso del curso se aligera, las progras son realizables, lo único es la forma de dar las clases lo que hace es leer diapositivas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-09T00:00:00+00:00'::TIMESTAMPTZ, '7ae6ba92963fa051d20b2dfbe54dafb6b20cc2c65b24876cf69afc032fc17634'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Pésimo curso, pésimo "profe". Puro Karaoke, habla raro, no se le entiende ni una palabra.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2017-06-07T00:00:00+00:00'::TIMESTAMPTZ, '1f2d55d8cffec0560fdf7b6f36257a03fc98ef1111233e62fbb231f0936018e9'::TEXT, ARRAY[1054]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-05-31T00:00:00+00:00'::TIMESTAMPTZ, '21d426bde4915bf930ca9879931f86d81c1885e7e609897e4a59d14d8862932d'::TEXT, ARRAY[1054]::BIGINT[]),
    (309::BIGINT, 'Clases basadas en Power Point, ¿explicación, qué es eso? Proyectos de programación camuflados de tareas con documentación excesiva. Si por lo menos supiera explicar no sería tan tedioso.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-04-21T00:00:00+00:00'::TIMESTAMPTZ, '0ab261fd39e060c4ef0b342d04bcd16fbf6e96c1258b2cacd0db06b276b6bb4e'::TEXT, ARRAY[1054]::BIGINT[]),
    (309::BIGINT, 'Qué dicha que quiere cambiar, pero lo que tiene que saber es que dejando trabajos más difíciles no ayudan en nada si él lo único que hace en clases es pasar las diapositivas. Deja las cosas porque sí y no enseña realmente. Debería ser un curso virtual. Sin profesor. Sólo Google.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-04-15T00:00:00+00:00'::TIMESTAMPTZ, 'c6f4912eb3e8a783437745f1eb11e55a07d8529776dd4d6c12406f5f24e5a1a8'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Las clases desmotivan, hace quices a cada rato sin avisar, no se sabe que esperar del curso, deja tareas innecesariamente largas; en otras palabras, es un profe sumamente incómodo para llevar un curso. No lo recomiendo para nada. Es mejor llevar con otro profesor aunque sea más difícil.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2017-03-16T00:00:00+00:00'::TIMESTAMPTZ, 'a0e4012b1ce710218d11bfb11bdfeb82acfffedca0038db737ecd62ca1be3738'::TEXT, ARRAY[1054]::BIGINT[]),
    (309::BIGINT, 'Al mae no le estresa nada, es muy buen profe explica bastante bien y se preocupa porque uno aprenda'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'e1f5bcdad2c923b2270866c3376309d49ebffeeb5f67179ae1f9411e430cc788'::TEXT, ARRAY[1054]::BIGINT[]),
    (309::BIGINT, 'Muy buen profesor! Realmente se aprende y lleva el control de notas al día'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'ba708642db9a4baeacad8e9d3b3d6692388e51d6ef85131bdaba78ef7cc8e65a'::TEXT, ARRAY[1054]::BIGINT[]),
    (309::BIGINT, 'Buen profesor, explica bien, tiene muchas ideas interesantes por hacer y no califica muy'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-04T00:00:00+00:00'::TIMESTAMPTZ, '80b1dcaa7bf7dec237fce2fb218c6bd9d5a88cd6ab83bd6266e213ff357fc656'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'No es mal profe, pero un poco de practica relacionado al tema en clase no cae mal, se fue mucho por la teoria, se desvia un poco del tema, llega tarde lo q hace que no cubra bien los temas, si ayuda lo q es bueno, pero podria hacer que la clase sea mas provechosa para los estudiantes y para él'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '30003a922690214134c210e37ba3d7dd718a725abc608f9b55a0eab15ed11d05'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'Muy buen profesor, explica bien y las clases son muy entretenidas e interesantes. Deja varias tareas para poder lograr hacer los proyectos. Seria mucho mejor si no llegara tan tarde.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'a0aca7002dc51e13cadd6714fed4f8b6e27f8d2841f46f636e96c58ea0814c99'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, '¡Es muy buen profe! Se interesa por el estudiante y su aprendizaje. A veces le falta un poco explicar más algunos aspectos, pero no es nada que una consulta no pueda aclarar. Es comprensivo, buena gente y las clases se pasan bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'fbbd802ddfaf77d9c2d7dd4282a4ed32d9f81b660fbca8fdb090c0255b49ab44'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'Llega a leer diapositivas y le falta dar más ejemplos y explicarlos, más por el tipo de curso que es. Se pasa fácil pero hay que investigar mucho por cuenta propia.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'bbdec97a6102feaeef7d232f861ad7b501b2727ef9432cfd94b5735d63091212'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'Si se le da el tiempo que el curso requiere, no es difícil pasar con una buena nota. Bastantes puntos extra por esfuerzo (extra). Creo que el profe podría comprometerse más con el curso, pero por otras actividades en las que está se le complica.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '92e5a22c3b2d98db3a1ea7e4eada831f1dea8841294c66a3721e6b5fa3ff90ef'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'Estructuras de datos, los temas son fáciles, pero el nivel información que se debe asimilar en los ejemplos y las clases en general hacen que en relación a la curva de aprendizaje, se vuelva un poco difícil de entender en primera instancia. califica en parte por el esfuerzo, aunque todo se caiga.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '4efb55bebd1c7ec8743bfad6067ed54d5d29a911d58b4e46f753c9cf7fbc8aa2'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-05T00:00:00+00:00'::TIMESTAMPTZ, '3e404c2a0281d28d66934a12f8201c2d93025a5bb00cd722f36e6660586e2c76'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-04T00:00:00+00:00'::TIMESTAMPTZ, '6bc2854904b32a6066c18296125fd4d465a0829b61a9795744a8d190fc00195a'::TEXT, ARRAY[1029]::BIGINT[]),
    (309::BIGINT, 'Es un muy buen profe, enseña muy claro y la materia es interesante a diferencia de otros, hace las clases entretenidas y ayuda mucho si usted hace todos los trabajos en el semestre, además da muchos ejercicios por puntos extra'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-03T00:00:00+00:00'::TIMESTAMPTZ, '23c4bbc0609b9afcbe27861db925e061bc352586908dc78998cecec83585432a'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Deja mucha tarea, pero son fáciles. Los proyectos que deja son muy interesantes y logrables. Al final es muy bondadoso calificando.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2016-02-21T00:00:00+00:00'::TIMESTAMPTZ, '716fe17a53a96b3f83425303d24fdbdeef28674d6b61e86bb46abe3ec0b473b6'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Como quien dice "Llega siempre a la hora del mono", pero es muy buen profe, explica bastante bien y es muy buena gente, eso si las progras cuestan un güevo (si con "g"), pero si llevo fundamentos con un buen profe no le va a ser difícil pasar'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ae52832f10e23d1e39874e0f039a21a41439003bba5bcadb960c30fb9b404019'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'El único problema con este profe es la imputualidad, sin embargo, siempre termina de dar la materia. Es buen profe, sabe mucho y le interesa que los estudiantes aprendan. Es flexible con el tiempo. Deja trabajos muy bonitos y retadores. Ha bastantes tareas. Es buena gente.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-18T00:00:00+00:00'::TIMESTAMPTZ, '506c79bf64640095989275ee186a614f2244b64bb00bc9e837841152a1f550d8'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Los proyectos no son fáciles, y el pedirle ayuda no siempre hace alguna diferencia. Es muy impuntual. Por otro lado, evalúa sin ser muy estricto, es muy buena gente, da suficiente tiempo para proyectos y deja suficientes tareas que ayudan a subir el promedio(si se hacen, obvio).'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'a8910059c18b8ffc8240cce9c9440ed8fb59d06f71a071da63e2386200c8afca'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Es buen profe, se preocupa por que uno le entienda. Deja tareas que le ayudan a estudiar y a ganarse la nota a poquitos. Los proyectos son larguillos, pero no imposibles. Califica relajado. Los exámenes son de leer bien porque cualquiera de las opciones puede ser jaja. Es muy buena gente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-01T00:00:00+00:00'::TIMESTAMPTZ, '31f13781e946b231858581416e93ac96382d3a8735feac3ee73d016785cba72b'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Es un profesor respetuoso y las clases son agradables, aunque es demasiado impuntual. Deja muchas tareas, no son difíciles, pero quitan mucho tiempo. Es una buena opción.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ce207ea79963ceb0e85592a27cfa808c5c8113a71be1906aa7636556f3f60235'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Bastante impuntual y algo desordenado con la evaluación del curso. Tiene buenas intenciones para el curso pero parece tener dificultad al llevarla a proyectos. Énfasis demasiado teórico y se olvida de la implementación práctica de lo visto en clase. Evaluación floja pero explica todo bien pero flojo'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'dc4ddb03afb1b4686b7f6b3ad39672d8f80dce19c47a645cef53aef7ccd399aa'::TEXT, ARRAY[1035]::BIGINT[]),
    (309::BIGINT, 'llega 30 min tarde de fijo, deja muchos trabajos spam, el principio del semestre estuvo bien ya que explicaba claramente, la segunda parte fue un poco desordenada, aprendimos arduino practicamente solos y la materia no fue bien estructurada pero nos da proyectos interesantes y es buena persona'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '6258b76f26de93e4bb5b4201eb497979ca1d86d6f22e5e4c9c915f53d7b8d7bd'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, '57baa1f6a486c4f3dcebfb812b4e2ad2061ff6ed7f21bc93aa930c34e49acc77'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Es un profesor muy buena gente. Es paciente y le ayuda a uno cuando se necesite. Se nota que domina muy bien los contenidos del curso y trata de hacer proyectos interesantes donde se aprende mucho (y hasta de electrónica). Las lecciones son como de una hora y 15 y son interesantes. Muy recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, '7dbf4d8d803d0b660e03a6409d08cbce8494528410bff7b8bd0436dfbd1a67e8'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'El compa siempre llega tarde media hora es necesario traerse alguna distracción, explica muy bien sin embargo deja muchos trabajos spam (16 resumenes A MANO entre otras cosas), en general buena experiencia a pesar del spam de trabajo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-17T00:00:00+00:00'::TIMESTAMPTZ, '9614dbaba1b04301d4aa7069918544512d1934d8f9b8b7ad9b53ac872b45fd8f'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Nunca llegó temprano en todo el curso, alrededor de una hora tarde y al hacerlo no tenía preparada la clase por lo que parecía que improvisaba con unas presentaciones. La materia dada por el en la pizarra es bastante clare y lo mantiene atento.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'bf03fd924c61dc318baa8f060e2b8cbcea06c0db2690c000b023cf9df2222b46'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Muy buen profesor. Las clases son de 1h y se aprende. Los exámenes son fáciles pero uno que otro proyecto no. Me gustó mucho el curso.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-09T00:00:00+00:00'::TIMESTAMPTZ, '7bb5bae537797ba4c5fc865f245ea12f6e0ba456bb3cc6b5b6b0fe3577a00c5f'::TEXT, ARRAY[1035]::BIGINT[]),
    (309::BIGINT, 'Es relativamente fácil, pero si tiene uno que otro trabajo dificil, con él la idea es hacerlos todos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-09T00:00:00+00:00'::TIMESTAMPTZ, '004ffbd4656cf2485eca195ec16342b065403fcefcad2a56a98453f3fc78b119'::TEXT, ARRAY[1035]::BIGINT[]),
    (309::BIGINT, 'Es un buen profe, comprensible con los proyectos (no por la dificultad, sino porque puede aveces aplazar la fecha con tal de ver mejores proyectos). Para el curso de análisis fue un poco aburrido (tal vez por la materia), pero en Arqui fue un curso interesante donde se aprende bastante. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'a86aca30f432efca2fb7080b7a4615d9d2f21454b27e8f7c543bcd3212c87924'::TEXT, ARRAY[1035]::BIGINT[]),
    (309::BIGINT, 'Excelente profesor, y muy buena persona también, posee muchos conocimientos y se nota que le gusta que los estudiantes aprendan, aunque loe falta pulirse en la puntualidad'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-07T00:00:00+00:00'::TIMESTAMPTZ, '538a7d256cf17b5b4255dcc5fbef88759caa53debd6ef4071e48ee756ba7c6b9'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Excelente profe, nada más que decir'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'c534af0cf48d5d8a9513969b8bb695a3d523df1fac94f07ed5112b852c5b7a2f'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Se aprende bastante, no es matador y las clases son divertidas. Es mi primera opción para los demás cursos ya que este no acapara todo el tiempo si no solo el necesario para poder llevar otras materias'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'e1c2ce7f9f7d210a059c2ea0ab14ab2e5377f8b0556067a0e982091e12d733d6'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Muy buen profe, su conocimiento y manejo de los temas son excelentes solamente que es difícil adaptar las clases por sus llegadas tardías, se aprovecharían mas si fuera puntual y no andar viendo la materia un poco en carrera. Los proyectos que deja muy buenos respecto a lo que se debe calificar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'fc1e22cbdb2841ae8d203a34da6c24bde28e8aaa2974c3afdb57fe051294977c'::TEXT, ARRAY[1154]::BIGINT[]),
    (309::BIGINT, 'Es un excelente profesor, se aprende muchísimo, tal vez deja tareas algo pesadas, pero es muy flexible. da los temas con claridad, y los trabajos son interesantes. Recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '8143b00556819a09d79200124a9356e50764000334500cd9814d8399a4d92783'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Si quiere llevar FOC y a la vez aprender, disfrutar y tener la posibilidad de pasar los demás cursos del semestre, matricule con Esteban. Otros profesores son pésimos o son en extremo exigentes y acaparan todo el tiempo disponible. Esteban será mi primera opción en los siguientes cursos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '05599adfc6751a1c7f647745b585c210bb625042b9742d5935d3448e34cb66a9'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Excelente profesor en mi caso reconozco que a la hora de explicar es claro , y los proyectos me parecieron muy buenos e interesantes .'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'ac722dc798ca5336cbc6d7920a5bf3d1efc67694bc3df93afc5f4caac8cd9562'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Es excelente, tiene una metodología excelente para dar clases, enseña bien , es muy claro a la hora de hablar y NO TORTURA a los estudiantes como otros. Muy dinámico y las clases no se hacen aburridas. Lo recomiendo!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'b713891790114c4905e4990e2c80c1a502e57a29a4dad555dc3677829d437cb9'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Es un profe demasiado buena gente, se lleva muy bien con el estudiante, y lo más importante es que sabe y la materia que da es totalmente entendible; el único detalle es que casi siempre llega un poco tarde pero a parte de eso es un buen profesor. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '7623bc76cb41134f881fe4e301003916a11baf294eb27cfe6b9cf998cf211931'::TEXT, ARRAY[1035]::BIGINT[]),
    (309::BIGINT, 'Muy bueno, se le entiende todo lo que explica. Califica normal, se preocupa porque el estudiante aprenda. Los proyectos son interesantes y se aprenden bastante de ello. Deja resumenes nutridos, pero es parte del metodo de aprendizaje y sirven demasiado en los examenes. 100% recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '90a600dd71728472808887804bf2a2dbcc6e109f1887b9221efc85be5d25a469'::TEXT, ARRAY[1017]::BIGINT[]),
    (309::BIGINT, 'Un muy buen profesor, si uno tiene dudas el las atiende, explica muy bien la materia y se ve que sabe demasiado de la misma, siempre llega tarde a clases pero aparte de eso un excelente profesor. Las progras son bastante realizables, solo es ponerle y enviar todos los trabajos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '0b6b03027975f227b6a9ec4f70b2d663dfbcd259043d8bcc7fe0f6ff83b5585b'::TEXT, ARRAY[1035]::BIGINT[]),
    (309::BIGINT, 'Si tiene dudas, pregunte.Si quiere pasar fácilmente, haga todos los trabajos. Respecto a los proyectos, si los hace con cariño son interesantes. El profesor es buena gente, y se preocupa por que usted entienda y aprenda. Bastante impuntual, pero llegue siempre temprano a clases por si acaso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '2744aa67b75039f2ebbcfdf577bf7d3d0a98606c721e278a0a2df42f80c21873'::TEXT, ARRAY[1035]::BIGINT[]),
    (309::BIGINT, 'Es un excelente profesor, vale la pena llevar cualquier curso con el.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'fc78b3f8c0d8fade642c1b17820d650826e00643cf4f49bc6aad41999112cbce'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Muy impuntual. Mínimo media hora tarde todos los días. Pero se ve que él sabe un montón. Los proyectos sí son medio complejos comparados con lo que enseña, pero son muy interesantes y uno aprende un montón. Los exámenes son muy fáciles. Es muy generoso revisando. No es difícil pasar el curso.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'cc7ccbc11020aa3c0429ec18b32d38f44f20b8ff34a66a9aca57405a6fb83ab0'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Buen profe, los proyectos fueron divertidos. Exámenes muy fácil, uno pasa con solo asistir y hacer los proyectos. Podría ser un poco mas retador...'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '7428b414eedc9164c6e5f5e9725f22434be2d5c96009d518c2b0caf664601adf'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Muy muy impuntual'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '40'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-13T00:00:00+00:00'::TIMESTAMPTZ, '4b20b0d0d14091b7c840edea91cd4024b4139264ee04d7141c296deee40f4843'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Explica bastante bien, de echo todo lo que no sabia de funda lo aprendi en arqui con el.. Los proyectos son interesantes y se aprende bastante bien ensamblador. Califica suave y es generoso. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'aa0c7185ca33e7c0c4416f151779a0d26aa0a22865495e45d14d9a84dd814a1c'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'El curso es muy interesante; se aprende bastante sobre el funcionamiento de la PC. A mitad de semestre es más ensamblador y las clases se vuelven más aburridas. Los proyectos son casi a final de semestre y son bastante complejos pero a pesar de eso son muy pichudos. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, '95200127c3e39932f891404c09617fa9dc7e33e1d9947b3431b122bbecb6e2a4'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Es super impuntual; de llegar 30 mins tarde a todas las clases. Pero las clases son interesantes y los proyectos también. Además es generoso a la hora de calificar tareas y proyectos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '691b402d1da1b598214b6361d4504018ed41e74af5e35cb244d4014ce27ab869'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '20'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '0d58712dfdd06c652502614fbeed7ef50f6e2d812b94669db5cf1ccc29357928'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '50'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '9727f5e1885b6a4ed54e74d3520e09791ce36c5745b6f34ac2e657c94ff3b596'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '48108f59d546dcc053d48d0a399a93059a321998d8c69a06a143d7807c6969d8'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Profe un poco desordenado con el tiempo y MUY impuntual. Pero tiene muchas ideas interesantes para el curso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '2aee0042557bdb9df828051fd75c4c35ce780d0e3ae8d80bd9b40ad67d0fa0b8'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'ad93452f1fb6a011fb489446cdbc3c1f7a73f105d83f19cc352306b7c9853ffe'::TEXT, ARRAY[1032]::BIGINT[]),
    (309::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '9d0ffc8ce6a8047fd92a750f1f045e82282e117886b44407d20f3b3d2f9578cd'::TEXT, ARRAY[1032, 1054]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
